"""Mapping (row, column, spin-type) to Jordan-Wigner encoding.

    Args:
        nhoriz -- number of horizontal sites
        nvert -- number of vertical sites
        row -- row location of the qubit in the lattice
        col -- column location of the qubit in the lattice
        spin -- spin-type: up or down

    Returns:
        Number of Jordan-Wigner encoded qubit
    """
def map_rcs_to_JW(nh: Any, nv: Any, row: Any, col: Any, spin: Any) -> object {
    col_adjust = col;
    if ((row % 2) == 1) {
        col_adjust = nh - 1 - col;
    }
    return ((row * nh) + col_adjust + (nh * nv * spin));
}

"""
      diff(a:iterable, b: iterable)
          a - b; elements in a but not in b

      args:
          a: iterable, b: iterable => eg: [1,2,3], [1]
      return:
          a list of (a - b)        => eg: [2,3]
    """
def diff(a: Any, b: Any) -> object {
    ans = [];
    sb = `set(b);
    for e in a {
        if (e not in sb) {
            ans.append(e);
        }
    }
    return ans;
}

"""
    Return minimum number of precincts that could be "bad".
       L = list of n precincts: n (size,name) pairs
       M = margin of victory as number of votes separating winner
           from runner-up
       s = maximum within-precinct miscount
    """
def bmin(L: Any, M: Any, s: Any = 0.2) -> object {
    assert (0 <= M <= sum(x[0] for x in L));
    votes_so_far = 0;
    k = 0;
    while ((votes_so_far < M) and (k < len(L))) {
        votes_so_far += 2.0 * s * L[k][0];
        k += 1;
    }
    return k;
}

