"""Helper to provide a key function for `sorted`

    Provide key to sort by type first and by whatever identifies a particular
    type of spec dict

    Parameters
    ----------
    spec: dict
      study specification dictionary

    Returns
    -------
    string
    """
def sort_spec(spec: Any) -> object {
    if (spec['type'] == 'dicomseries') {
        return ('dicomseries' + spec['uid']);
    } else {
        return (spec['type'] + spec['location']);
    }
}

""" (list, fn) -> list

    Takes a list of events as well as a function that is called on each event.
    A list is returned, which is composed of the return values from the
    function.

    """
def process_events(events: Any, fn: Any) -> object {
    aggregator = [];
    for event in events {
        aggregator.append(fn(event));
    }
    return aggregator;
}

"""
    Convert device_coordinate according to the tensor map.

    Args:
        device_coordinate (list): The coordinate for local device in the device matrix.
        tensor_map (list): The map relation between tensor and devices.

    Returns:
        List, the converted coordinate.
    """
def _convert_to_new_device_coordinate(
    device_coordinate: Any, tensor_map: Any
) -> object {
    device_coordinate_new = [];
    for i in range(len(tensor_map)) {
        if (tensor_map[(len(tensor_map) - 1 - i)] != -1) {
            device_coordinate_new.insert(
                0,
                device_coordinate[
                    (len(device_coordinate) - 1 - tensor_map[(len(tensor_map) - 1 - i)])
                ]
            );
        } else {
            device_coordinate_new.insert(0, 0);
        }
    }
    return device_coordinate_new;
}

